query.transform:
store.lines = store.lines or {}
table.insert(store.lines, 1, { at = os.date("%H:%M:%S"), stream = stream, line = rs })
while #store.lines > 10 do table.remove(store.lines) end
return { columns = { "at", "stream", "line" }, rows = vim.tbl_map(function(l)
  return { l.at, l.stream, l.line }
end, store.lines) }

-- Each item is "key=value": collect them into rows.
store.rows = store.rows or {}
local k, v = rs:match("^(%w+)=(.*)$")
table.insert(store.rows, { k, v })
return { columns = { "key", "value" }, rows = store.rows }
